<script setup lang="ts">
import type { Grant, Role } from '../api/people'
import type { Archive } from '../api/types'
const props=defineProps<{modelValue:Grant[];roles:Role[];scopeTypes:{code:string;name:string}[];orgs:Archive[];stores:Archive[];warehouses:Archive[]}>()
const emit=defineEmits<{'update:modelValue':[Grant[]]}>()
function update(index:number,key:keyof Grant,value:unknown){emit('update:modelValue',props.modelValue.map((g,i)=>i===index?{...g,[key]:value,...(key==='scope_type'?{scope_ids:[]}: {})}:g))}
function options(type:string){return type==='ORG_TREE'?props.orgs:type==='STORES'?props.stores:props.warehouses}
</script>
<template><div class="grant-editor"><p class="field-help">同一角色可按不同范围授权。全部、本组织、本人不需要指定对象。</p><div v-for="(grant,index) in modelValue" :key="index" class="panel editor-panel"><el-form-item label="角色"><el-select :model-value="grant.role_id" aria-label="授权角色" @update:model-value="update(index,'role_id',$event)"><el-option v-for="role in roles" :key="role.id" :label="role.name" :value="role.id"/></el-select></el-form-item><el-form-item label="数据范围"><el-select :model-value="grant.scope_type" aria-label="授权数据范围" @update:model-value="update(index,'scope_type',$event)"><el-option v-for="scope in scopeTypes" :key="scope.code" :label="scope.name" :value="scope.code"/></el-select></el-form-item><el-form-item v-if="['ORG_TREE','STORES','WAREHOUSES'].includes(grant.scope_type)" label="指定对象"><el-select :model-value="grant.scope_ids" multiple filterable aria-label="范围对象" @update:model-value="update(index,'scope_ids',$event)"><el-option v-for="item in options(grant.scope_type)" :key="item.id" :value="item.id" :label="`${item.name} · ${item.code}`"/></el-select></el-form-item><el-button type="danger" text @click="emit('update:modelValue',modelValue.filter((_,i)=>i!==index))">移除此授权</el-button></div><el-button @click="emit('update:modelValue',[...modelValue,{role_id:roles[0]?.id||0,scope_type:'SELF',scope_ids:[]}])">添加角色授权</el-button><p v-if="!modelValue.length" class="field-help">未配置角色授权，仅可查看本人档案。</p></div></template>
